LAUNCHER_PATCHES = [('Execute complete interior-restoration SO3 with explicitly bound retained T0 words.', 'Execute complete normalized-parent cached interior restoration and all-row SOC.'), ("DRIVER_SHA = '174b79f4b2393a719e7ddee70f59fe5c500e89d41e8d181497f1b4329f8b015f'", "DRIVER_SHA = '01b2a7777fea1979083c95d881da006d11885014c90c7f2dba7afd53d283aea9'"), ('fullclosed_so3_cached_interior_restore_qp.py', 'fullclosed_so3_cached_interior_separation_soc.py'), ("    p.add_argument('--line-trials', type=int, default=15)\n", "    p.add_argument('--line-trials', type=int, default=15)\n    p.add_argument('--soc-rounds', type=int, default=8)\n    p.add_argument('--soc-tau', type=float, default=0.)\n    p.add_argument('--soc-inward-fraction', type=float, default=.125)\n    p.add_argument('--soc-feasibility-tolerance', type=float, default=2.e-11)\n"), ('    a = p.parse_args()\n', "    a = p.parse_args()\n    if (not 1 <= a.soc_rounds <= 8 or any(not math.isfinite(v) or v < 0\n            for v in (a.soc_tau, a.soc_inward_fraction, a.soc_feasibility_tolerance))):\n        raise ValueError('Declare one-to-eight complete SOC rounds and finite nonnegative inward/readback parameters')\n"), ('public-actions-actual-fixed-parent-cached-interior-restore-SO3-command-v1', 'public-actions-complete-normalized-parent-cached-interior-separated-SOC-command-v1')]


def sha_text(source):
    return hashlib.sha256(source.encode()).hexdigest()


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def apply_exact(source, patches):
    for old, new in patches:
        if source.count(old) != 1:
            raise ValueError('Every complete replacement needs exactly one literal occurrence')
        source = source.replace(old, new, 1)
    return source


def validate_source(source, filename):
    tree = ast.parse(source, filename=filename)
    compile(tree, filename, 'exec')
    for node in ast.walk(tree):
        if isinstance(node, ast.Dict):
            keys = [key.value for key in node.keys if isinstance(key, ast.Constant)
                and isinstance(key.value, (str, int, float))]
            if len(keys) != len(set(keys)):
                raise ValueError('Duplicate literal dictionary key in '+filename)
    if any(line.rstrip() != line for line in source.splitlines()):
        raise ValueError('Complete source has trailing whitespace: '+filename)
    return tree


def source_pins(source):
    matches = [ast.literal_eval(node.value) for node in ast.parse(source).body
        if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name)
            and t.id == 'SOURCE_PINS' for t in node.targets)]
    if len(matches) != 1:
        raise ValueError('One complete literal source table is required')
    return matches[0]


def unchanged_functions(original, derived):
    a, b = ast.parse(original), ast.parse(derived)
    top_a = {n.name: n for n in a.body if isinstance(n, (ast.FunctionDef, ast.ClassDef))}
    top_b = {n.name: n for n in b.body if isinstance(n, (ast.FunctionDef, ast.ClassDef))}
    if set(top_a) != set(top_b):
        raise ValueError('Keep all complete original top-level interfaces')
    for name in top_a:
        if name not in ('main', 'parse_args') and ast.dump(top_a[name]) != ast.dump(top_b[name]):
            raise ValueError('Changed original full physical/coordinate interface: '+name)
    local_a = {n.name: n for n in top_a['main'].body if isinstance(n, ast.FunctionDef)}
    local_b = {n.name: n for n in top_b['main'].body if isinstance(n, ast.FunctionDef)}
    if set(local_a) != set(local_b):
        raise ValueError('Keep all original full statistics, permanent memory and cache interfaces')
    for name in local_a:
        if ast.dump(local_a[name]) != ast.dump(local_b[name]):
            raise ValueError('Changed original same-field local read: '+name)


def unchanged_helper_methods(original, derived, *, changed):
    def functions(source):
        result = {}
        for node in ast.parse(source).body:
            if isinstance(node, ast.FunctionDef):
                result[node.name] = node
            elif isinstance(node, ast.ClassDef):
                for method in node.body:
                    if isinstance(method, ast.FunctionDef):
                        result[node.name+'.'+method.name] = method
        return result
    old, new = functions(original), functions(derived)
    if set(old) != set(new):
        raise ValueError('A complete helper interface was omitted')
    for name in old:
        if name not in changed and ast.dump(old[name]) != ast.dump(new[name]):
            raise ValueError('An unrelated helper formula or complete scope changed: '+name)


def derive_driver(original, helper, cache):
    if (sha_text(original) != ORIGINAL_DRIVER_SHA or sha_text(helper) != HELPER_SHA
            or sha_text(cache) != CACHE_SHA):
        raise ValueError('Bind the entire actual base and both full new helper sources')
    result = apply_exact(original, DRIVER_PATCHES)
    validate_source(helper, 'complete_normalized_parent_so3_rows_soc.py')
    validate_source(cache, 'so3_frozen_parent_cache_for_soc.py')
    validate_source(result, 'fullclosed_so3_cached_interior_separation_soc.py')
    unchanged_functions(original, result)
    old_pins, new_pins = source_pins(original), source_pins(result)
    for role, item in old_pins.items():
        if role != 'reference_cache' and new_pins.get(role) != item:
            raise ValueError('An original physical/norm/objective/QP source changed: '+role)
    if new_pins['predecessor_reference_cache'] != old_pins['reference_cache']:
        raise ValueError('Keep the old numerical cache source as its own actual input identity')
    if sha_text(result) != DERIVED_DRIVER_SHA:
        raise ValueError('The entire complete derived driver differs')
    return result


def derive_launcher(original, driver):
    if sha_text(original) != ORIGINAL_LAUNCHER_SHA or sha_text(driver) != DERIVED_DRIVER_SHA:
        raise ValueError('Bind the entire original launcher and complete derived driver')
    result = apply_exact(original, LAUNCHER_PATCHES)
    validate_source(result, 'launch_so3_cached_interior_separation_soc.py')
    if sha_text(result) != DERIVED_LAUNCHER_SHA:
        raise ValueError('The entire derived launcher differs')
    return result


def bind_report(repo, report_path):
    topic = Path(repo).resolve()/'topics/visible-flex-larger-amplitude'
    directory = topic/'scripts/resume_20261126'
    original = directory/'fullclosed_so3_cached_interior_restore_qp.py'
    helper = directory/'complete_normalized_parent_so3_rows_soc.py'
    cache = directory/'so3_frozen_parent_cache_for_soc.py'
    driver = directory/'fullclosed_so3_cached_interior_separation_soc.py'
    expected = derive_driver(original.read_text(), helper.read_text(), cache.read_text())
    if driver.read_text() != expected or sha(driver) != DERIVED_DRIVER_SHA:
        raise ValueError('The actual entire driver differs from its complete declared derivation')
    original_helper = directory/'complete_axisymmetric_so3_rows_soc.py'
    original_cache = directory/'so3_frozen_parent_cache.py'
    if sha(original_helper) != ORIGINAL_SOC_HELPER_SHA or sha(original_cache) != ORIGINAL_CACHE_SHA:
        raise ValueError('Keep both actual original helper bodies independently attributed')
    unchanged_helper_methods(original_helper.read_text(), helper.read_text(),
        changed={'CompleteSO3RowsSOC.__init__'})
    unchanged_helper_methods(original_cache.read_text(), cache.read_text(),
        changed={'FrozenParentCache._adopt'})
    report = json.loads(Path(report_path).read_text())
    if report.get('schema') != SCHEMA or report.get('source_sha256') != DERIVED_DRIVER_SHA:
        raise ValueError('The report belongs to another entire actual source/schema')
    pins = source_pins(expected)
    if report.get('source_sha256_by_role') != {key: value[1] for key, value in pins.items()}:
        raise ValueError('The actual complete source-role registry differs')
    for role, (relative, digest) in pins.items():
        if sha(topic/relative) != digest:
            raise ValueError('Changed actual source role '+role)
    return dict(actual_driver_sha256=DERIVED_DRIVER_SHA, actual_entire_body_match=True,
        original_complete_cached_driver_sha256=ORIGINAL_DRIVER_SHA,
        original_complete_typed_SOC_helper_sha256=ORIGINAL_SOC_HELPER_SHA,
        complete_normalized_parent_SOC_helper_sha256=HELPER_SHA,
        complete_cache_binding_source_sha256=CACHE_SHA,
        original_cache_binding_source_sha256=ORIGINAL_CACHE_SHA,
        projection_sha256=PROJECTION_SHA, original_physical_sources_unchanged=True,
        exact_full_interior_Phase_I_class_unchanged=True,
        all_existing_full_statistics_and_memory_functions_unchanged=True,
        actual_source_commit=report.get('source_commit'),
        model_identity_sha256=report.get('model_identity_sha256'),
        raw_scientific_arrays_recomputed=False, field_calls=0, J_calls=0,
        geometric_feasibility_or_convergence_inferred=False)


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--original-driver', type=Path, required=True)
    p.add_argument('--original-launcher', type=Path, required=True)
    p.add_argument('--helper', type=Path, required=True)
    p.add_argument('--cache-helper', type=Path, required=True)
    p.add_argument('--outdir', type=Path, required=True)
    p.add_argument('--verify-existing', action='store_true')
    a = p.parse_args()
    driver = derive_driver(a.original_driver.read_text(), a.helper.read_text(), a.cache_helper.read_text())
    launcher = derive_launcher(a.original_launcher.read_text(), driver)
    a.outdir.mkdir(parents=True, exist_ok=True)
    for name, source in (('fullclosed_so3_cached_interior_separation_soc.py', driver),
            ('launch_so3_cached_interior_separation_soc.py', launcher)):
        path = a.outdir/name
        if a.verify_existing:
            if path.read_text() != source:
                raise ValueError('Complete existing source differs: '+str(path))
        else:
            if path.exists():
                raise FileExistsError('Do not overwrite a previously generated source')
            path.write_text(source)
    print(json.dumps(dict(complete=True, pure_source_derivation=True,
        numerical_modules_imported=False, scientific_execution=False,
        driver_sha256=DERIVED_DRIVER_SHA, launcher_sha256=DERIVED_LAUNCHER_SHA,
        helper_sha256=HELPER_SHA, cache_sha256=CACHE_SHA,
        source_sha256=sha(__file__)), sort_keys=True, allow_nan=False))


if __name__ == '__main__':
    main()
